		usb_set_interface(udev, ifnum, 1);
	}

	ignore_list = (const struct sierra_iface_list *)id->driver_info;

	if (is_listed(ifnum, ignore_list)) {
		dev_dbg(&serial->dev->dev, "Ignoring interface #%d\n", ifnum);
		return -ENODEV;
	}

	return result;
}

